{
  "$schema": "https://dsh.store/schema/bundle-patch/v1.json",
  "id": "dsh-lark-bridge",
  "name": "DSH Lark Bridge",
  "description": "Feishu (Lark) bot bridge for DeepSeek Harness — real-time chat, operation-approval routing, and session management via Feishu interactive cards.",
  "version": "0.2.0",
  "entry": "dsh-lark-bridge",
  "type": "bridge",
  "patch": [
    {
      "id": "dsh-lark-bridge:bot",
      "kind": "additive",
      "description": "Feishu ↔ DSH bridge bot process — long-connection WebSocket transport, multi-session isolation, slash commands, approval/question card routing.",
      "files": [
        "src/bot.js",
        "src/dsh/client.js",
        "src/feishu/bridge.js",
        "setup.mjs",
        "start-bot.bat"
      ]
    }
  ],
  "compatibility": {
    "node": ">=20",
    "dshReleases": {
      "0.1.0-rc.8": "compatible",
      "0.1.1-rc.1": "compatible",
      "0.1.1-rc.2": "compatible"
    }
  },
  "profile": {
    "install": "npm install",
    "start": "node src/bot.js",
    "uninstall": "Remove node_modules, .session-cache.json, .chat-session-map.json"
  }
}
